#include <iostream>
#include <queue>
#include <algorithm>
using namespace std;

const int MAXN = 25;
const int MAXE = 400005;
const int INF = 1000000007;
const int SRC = 501;
const int SNK = 502;

char gridA[MAXN][MAXN], gridB[MAXN][MAXN];
int safeDist[MAXN][MAXN];
int pairDist[MAXN][MAXN][MAXN][MAXN];
queue<int> bfs;
int moveX[4] = {-1, 1, 0, 0};
int moveY[4] = {0, 0, -1, 1};

struct Edge { int u, v, fl, c, nxt; } e[MAXE];
int edgeCnt, head[505], parentEdge[505], seen[505], depth[505], answer;

inline int id(int x, int y, int n) { return (x - 1) * n + y; }
inline int getX(int code, int n) { return (code - 1) / n + 1; }
inline int getY(int code, int n) { return (code - 1) % n + 1; }

inline void addEdge(int u, int v, int cap) {
    e[++edgeCnt] = {u, v, 0, cap, head[u]};
    head[u] = edgeCnt;
    e[++edgeCnt] = {v, u, 0, 0, head[v]};
    head[v] = edgeCnt;
}

inline bool bfsLevel() {
    queue<int> qu;
    for (int i = 0; i <= SNK; i++) seen[i] = depth[i] = 0;
    qu.push(SRC);
    seen[SRC] = 1;
    depth[SRC] = 1;
    while (!qu.empty()) {
        int x = qu.front(); qu.pop();
        for (int i = head[x]; i; i = e[i].nxt) {
            int y = e[i].v;
            if (!seen[y] && e[i].fl < e[i].c) {
                parentEdge[y] = i;
                seen[y] = 1;
                depth[y] = depth[x] + 1;
                qu.push(y);
                if (y == SNK) return true;
            }
        }
    }
    return false;
}

inline int sendFlow(int x, int now) {
    if (x == SNK || !now) return now;
    int rest = now;
    for (int i = head[x]; i; i = e[i].nxt) {
        int y = e[i].v;
        if (e[i].c > e[i].fl && depth[y] == depth[x] + 1) {
            int pushed = sendFlow(y, min(rest, e[i].c - e[i].fl));
            if (!pushed) depth[y] = 0;
            e[i].fl += pushed;
            e[((i - 1) ^ 1) + 1].fl -= pushed;
            rest -= pushed;
            if (rest == 0) break;
        }
    }
    return now - rest;
}

inline void dinic() {
    while (bfsLevel()) answer += sendFlow(SRC, INF);
}

int main() {
    int n, timeLimit;
    cin >> n >> timeLimit;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            safeDist[i][j] = 10000;
            cin >> gridA[i][j];
            if (gridA[i][j] == 'Z') {
                bfs.push(id(i, j, n));
                safeDist[i][j] = 0;
            }
            if (gridA[i][j] <= '9')
                addEdge(SRC, id(i, j, n), gridA[i][j] - '0');
        }
    }
    while (!bfs.empty()) {
        int code = bfs.front(); bfs.pop();
        int x = getX(code, n), y = getY(code, n);
        for (int d = 0; d < 4; d++) {
            int nx = x + moveX[d], ny = y + moveY[d];
            if (nx > 0 && ny > 0 && nx <= n && ny <= n && gridA[nx][ny] <= '9' &&
                safeDist[nx][ny] > safeDist[x][y] + 1) {
                safeDist[nx][ny] = safeDist[x][y] + 1;
                bfs.push(id(nx, ny, n));
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (gridA[i][j] > '9') continue;
            int start = id(i, j, n);
            for (int k = 1; k <= n; k++)
                for (int l = 1; l <= n; l++)
                    pairDist[i][j][k][l] = 10000;
            bfs.push(start);
            pairDist[i][j][i][j] = 0;
            while (!bfs.empty()) {
                int code = bfs.front(); bfs.pop();
                int x = getX(code, n), y = getY(code, n);
                for (int f = 0; f < 4; f++) {
                    int nx = x + moveX[f], ny = y + moveY[f];
                    if (nx > 0 && ny > 0 && nx <= n && ny <= n && gridA[nx][ny] <= '9' &&
                        pairDist[i][j][nx][ny] > pairDist[i][j][x][y] + 1 &&
                        pairDist[i][j][x][y] < safeDist[x][y]) {
                        pairDist[i][j][nx][ny] = pairDist[i][j][x][y] + 1;
                        bfs.push(id(nx, ny, n));
                    }
                }
            }
            for (int k = 1; k <= n; k++)
                for (int l = 1; l <= n; l++)
                    if (pairDist[i][j][k][l] <= min(safeDist[k][l], timeLimit))
                        addEdge(start, id(k, l, n) + 100, 10000);
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            cin >> gridB[i][j];
            if (gridB[i][j] <= '9')
                addEdge(id(i, j, n) + 100, SNK, gridB[i][j] - '0');
        }
    }
    dinic();
    cout << answer;
    return 0;
}
